<template><view class="page"><view v-if="employee" class="profile card"><view class="avatar">{{ employee.name.slice(0,1) }}</view><view><text class="name">{{ employee.name }}</text><text>{{ employee.role }} · {{ employee.store }}</text></view></view><view class="notice">演示数据仅保存在当前微信客户端，不连接生产系统。</view><view class="card actions"><button @tap="reset">重置演示数据</button><button @tap="signOut">退出当前账号</button></view><view class="info"><text>演示版本 1.0.0</text><text>仅用于个人待办与顾客档案展示</text></view></view></template>
<script setup>
import { ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { getSession, logout, resetDemoData } from '../../services/repository'
const employee=ref(null);onShow(()=>{employee.value=getSession();if(!employee.value)uni.reLaunch({url:'/pages/login/index'})});function signOut(){logout();uni.reLaunch({url:'/pages/login/index'})}function reset(){uni.showModal({title:'重置演示数据',content:'将恢复初始样例并退出登录，是否继续？',success:res=>{if(res.confirm){resetDemoData();uni.reLaunch({url:'/pages/login/index'})}}})}
</script><style scoped>.profile{display:flex;align-items:center;margin:12rpx 0 22rpx;padding:28rpx}.avatar{width:86rpx;height:86rpx;line-height:86rpx;border-radius:50%;background:#e9f1ff;color:#2167e8;text-align:center;font-size:34rpx;font-weight:700}.profile view:last-child{margin-left:20rpx}.profile text{display:block;margin-top:8rpx;color:#7b8494;font-size:24rpx}.profile .name{margin:0;color:#182033;font-size:33rpx;font-weight:700}.actions{overflow:hidden}.actions button{background:#fff;border-radius:0;border-bottom:1rpx solid #edf0f5;color:#182033;text-align:left;padding:24rpx;font-size:28rpx}.actions button:last-child{border:0;color:#c72d2d}.info{margin:36rpx;text-align:center;color:#8a94a5;font-size:23rpx}.info text{display:block;margin-top:8rpx}</style>
